const jsdom = require('jsdom');
let htmlDOM = new jsdom.JSDOM(html);

let output = "champion;genre;role;espece;ressource;type-de-portee;region;year\n"

let table = document.getElementsByClassName('answers-container')[0].children;
for (let i = 0; i < table.length; i++) {
    const row = table[i].children[0].children;
    for (let j = 0; j < row.length; j++) {
        if (j == 0) {
            output += row[j].textContent.replace(/  .*/, "").slice(1) + ";"
        }
        else {
          output += row[j].textContent.slice(1, -1) + ";"
        };
    }
    output.slice(0,-1);
    output += "\n";
}
console.log(output)